// Helper: get all questions as flat array
export const getAllQuestions = () => {
  return Object.values(quizData).flatMap(topic => topic.questions);
};

// Helper: get questions by topic
export const getQuestionsByTopic = (topicId) => {
  return quizData[topicId]?.questions || [];
};

// Helper: get questions by subtopic
export const getQuestionsBySubtopic = (subtopic) => {
  return getAllQuestions().filter(q => q.subtopic === subtopic);
};

// Helper: get total question count
export const getTotalQuestionCount = () => getAllQuestions().length;
